// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import { config } from "dotenv";
import { defineConfig } from "prisma/config";

// Same precedence as Next.js: .env.local (local Docker database, see
// docker-compose.yml) wins over .env. Neither exists in GitHub Actions, where
// the migration workflow supplies DATABASE_URL/DIRECT_URL as secrets.
config({ path: [".env.local", ".env"], quiet: true });

// Migrate/introspect/studio need a direct (non-pooled) connection.
// The app runtime uses DATABASE_URL (pooled) via the driver adapter in src/lib/db.ts.
export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: process.env["DIRECT_URL"] ?? process.env["DATABASE_URL"],
  },
});
